}

/**
 * A link with no wrapper of its own. The provider component receives the
 * original props directly, so the rendered DOM and styling stay with the
 * router's link implementation. A per-link component or `as` can override it.
 */
export type FoglampLinkProps<Component extends FoglampLinkComponent = "a"> =
	React.ComponentPropsWithRef<Component> & {
		component?: Component;
		as?: Component;
		/** Common router destination prop, available with the default anchor type. */
		to?: string;
	};

export function FoglampLink<Component extends FoglampLinkComponent = "a">({
	component,
	as,
	...props
}: FoglampLinkProps<Component>) {
	const providerComponent = React.useContext(FoglampLinkContext);
	const LinkComponent = component ?? as ?? providerComponent;

	return React.createElement(LinkComponent, props as React.ComponentPropsWithRef<Component>);
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
export const ALERT_METRICS = [
  "cost",
  "latency_p50",
  "latency_p95",
  "latency_p99",
  "ttft_p95",
  "error_rate",
  "token_usage",
  "request_count",
  "eval_avg_score",
  "eval_pass_rate",
] as const;

export type AlertMetric = (typeof ALERT_METRICS)[number];

/** Metrics offered for newly-created rules. Legacy metrics remain readable and
 * evaluable so existing alerts do not break. */
export const CREATABLE_ALERT_METRICS = [
  "cost",
  "latency_p95",
  "error_rate",
  "eval_pass_rate",
] as const satisfies readonly AlertMetric[];

export type CreatableAlertMetric = (typeof CREATABLE_ALERT_METRICS)[number];

/** Evaluation windows the product has ever offered. Legacy windows remain
 * evaluable so existing alerts do not break. */
export const ALERT_WINDOW_SECONDS = [300, 900, 3600, 86_400] as const;

export type AlertWindowSeconds = (typeof ALERT_WINDOW_SECONDS)[number];

/** Windows offered for newly-created (or re-windowed) rules. 5m was dropped:
 * with a 60s sweep it is nearly all noise, and the anti-flap state machine
 * makes 15m the shortest useful detection window. */
export const CREATABLE_ALERT_WINDOW_SECONDS = [
  900, 3600, 86_400,
] as const satisfies readonly AlertWindowSeconds[];

export const ALERT_COMPARISONS = ["gt", "gte", "lt", "lte"] as const;
export type AlertComparison = (typeof ALERT_COMPARISONS)[number];

export const ALERT_METRIC_LABELS: Record<AlertMetric, string> = {
  cost: "Cost",
  latency_p50: "Latency p50",
  latency_p95: "Latency p95",
  latency_p99: "Latency p99",
  ttft_p95: "TTFT p95",
  error_rate: "Error rate",
  token_usage: "Token usage",
  request_count: "Request count",
  eval_avg_score: "Avg eval score",
  eval_pass_rate: "Eval pass rate",
};

export const ALERT_COMPARISON_SYMBOLS: Record<AlertComparison, string> = {
  gt: ">",
  gte: "≥",
  lt: "<",
  lte: "≤",
};

export const ALERT_COMPARISON_LABELS: Record<AlertComparison, string> = {
  gt: "above",
  gte: "at least",
  lt: "below",
  lte: "at most",
};

const number = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });
const currency = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 0,
  maximumFractionDigits: 4,
});

function formatMilliseconds(value: number): string {
  if (Math.abs(value) < 1000) return `${number.format(value)}ms`;
  return `${number.format(value / 1000)}s`;
}

/** Format the storage-unit value of an alert metric for names and compact UI. */
export function formatAlertMetricValue(
  metric: AlertMetric,
  value: number | null | undefined,
): string {
  if (value === null || value === undefined || !Number.isFinite(value))
    return "—";
  switch (metric) {
    case "cost":
      return currency.format(value);
    case "latency_p50":
    case "latency_p95":
    case "latency_p99":
    case "ttft_p95":
      return formatMilliseconds(value);
    case "error_rate":
    case "eval_pass_rate":
      return `${number.format(value * 100)}%`;
    case "eval_avg_score":
      return number.format(value);
    case "token_usage":
    case "request_count":
      return number.format(value);
  }
}

export function generateAlertName(input: {
  metric: AlertMetric;
  comparison: AlertComparison;
  threshold: number;
}): string {
  return `${ALERT_METRIC_LABELS[input.metric]} ${ALERT_COMPARISON_LABELS[input.comparison]} ${formatAlertMetricValue(input.metric, input.threshold)}`;
}

export function formatAlertWindow(seconds: number): string {
  if (seconds % 86_400 === 0) return `${seconds / 86_400}d`;
  if (seconds % 3600 === 0) return `${seconds / 3600}h`;
  if (seconds % 60 === 0) return `${seconds / 60}m`;
  return `${seconds}s`;
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
import { z } from "zod";

import { type GraphNode, ScanData } from "./scan";

/** Schema version for the plan payloads, independent of ScanData's version. */
export const PLAN_VERSION = 1;

// ---------------------------------------------------------------------------
// State machine
// ---------------------------------------------------------------------------

/**
 * The lifecycle of a plan. Persisted as text; the transition table below is the
 * only thing allowed to move a row between these.
 *
 *  - awaiting_approval: uploaded, the agent is polling, the user hasn't acted
 *  - approved:          the user said yes; the agent hasn't picked it up yet
 *  - applying:          the agent resumed and is editing the repo
 *  - applied:           code changes are in; waiting for the first real trace
 *  - verified:          a real span arrived — onboarding is complete
 *  - rejected:          the user said no; the agent exits cleanly
 *  - expired:           nobody acted before expiresAt; swept by the cron
 *  - failed:            the agent gave up (it reports which stage)
 *
 * Note there is no separate `waiting_for_trace` state: it would always coincide
 * exactly with `applied`, and two states that must flip together are a bug
 * waiting to happen. The UI renders `applied` as "Waiting for your first real
 * trace" — the user-facing distinction is copy, not state.
 */
export const PLAN_STATUSES = [
  "awaiting_approval",
  "approved",
  "applying",
  "applied",
  "verified",
  "rejected",
  "expired",
  "failed",
] as const;
export const PlanStatus = z.enum(PLAN_STATUSES);
export type PlanStatus = z.infer<typeof PlanStatus>;

/** Statuses from which nothing further can happen. */
export const TERMINAL_STATUSES = ["verified", "rejected", "expired", "failed"] as const;

/**
 * The only legal moves. Anything not listed is rejected — a status write can
 * never silently overwrite a terminal state, so a late-arriving agent request
 * can't un-reject or un-expire a plan.
 */
const TRANSITIONS: Record<PlanStatus, readonly PlanStatus[]> = {
  awaiting_approval: ["approved", "rejected", "expired"],
  approved: ["applying", "expired", "failed"],
  // `expired` here covers the agent that died mid-apply (crashed, laptop
  // closed): without it the plan would sit in `applying` forever and the
  // review page would spin until the end of time. The TTL is generous (24h),
  // so a healthy apply — minutes — never gets close.
  applying: ["applied", "expired", "failed"],
  applied: ["verified", "failed"],
  // Terminal — absorbing states.
  verified: [],
  rejected: [],
  expired: [],
  failed: [],
};

export function isTerminalStatus(status: PlanStatus): boolean {
  return (TERMINAL_STATUSES as readonly string[]).includes(status);
}

/**
 * Can a plan move from `from` to `to`? Pure — no I/O, no clock, no database.
 *
 * A self-transition (`from === to`) is always legal so that retries and
 * duplicate requests are no-ops rather than errors: the caller's conditional
 * `UPDATE ... WHERE status = <expected>` simply matches zero rows the second
 * time, which is exactly the idempotency we want.
 */
export function canTransition(from: PlanStatus, to: PlanStatus): boolean {
  if (from === to) return true;
  return TRANSITIONS[from].includes(to);
}

/** The statuses a plan can still leave — i.e. worth polling for a change. */
export function isPending(status: PlanStatus): boolean {
  return !isTerminalStatus(status);
}

// ---------------------------------------------------------------------------
// Shared primitives
// ---------------------------------------------------------------------------

/** Where something lives in the repo, e.g. "src/agents/support.ts:42". */
const SourceRef = z.string().min(1).max(160);

/** One short sentence explaining a recommendation. Never contains code. */
const Rationale = z.string().min(1).max(200);

/** How sure the agent is. Drives the review UI's emphasis, nothing else. */
export const Confidence = z.enum(["high", "medium", "low"]);
export type Confidence = z.infer<typeof Confidence>;

/**
 * A static name attached to a span (`agentName`, `workflowName`, `traceName`).
 * The constraint that matters: these must be stable literals so they group
 * across runs. Anything dynamic (an id, slug, URL, timestamp) belongs in
 * metadata / workflowRunId / sessionId / customer.id instead.
 */
const StaticName = z.string().min(1).max(48);

/**
 * A described source for a dynamic value, e.g. how to derive a workflowRunId.
 * Prose, not code: "the job id from the queue payload". The agent turns this
 * into an expression when it applies the plan.
 */
const ValueSource = z.string().min(1).max(160);

/** The AI SDK major this repo is on — decides wrap() vs fog.integration(). */
const SdkInfo = z
  .object({
    major: z.union([z.literal(4), z.literal(5), z.literal(6), z.literal(7)]),
    /** Exact installed version string, e.g. "5.0.12". Display only. */
    version: z.string().min(1).max(32),
  })
  .strict();
export type SdkInfo = z.infer<typeof SdkInfo>;

/** A single model call site found in the repo. */
const CallSite = z
  .object({
    /** Unique within the plan; referenced by decisions. */
    id: z.string().min(1).max(64),
    /** The AI SDK function called, e.g. "streamText". */
    fn: z.string().min(1).max(40),
    sourceRef: SourceRef,
    /** Model id if statically determinable, e.g. "gpt-4o". */
    modelId: z.string().max(64).optional(),
  })
  .strict();
export type CallSite = z.infer<typeof CallSite>;

// ---------------------------------------------------------------------------
// Decisions — the reviewable part
// ---------------------------------------------------------------------------

/**
 * A named agent flow. `oneOff` marks calls that aren't a repeated agent at all
 * (a one-shot classification, a title generator) — those get a `traceName`
 * rather than an `agentName`.
 */
const AgentDecision = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName,
    /** Call site ids this name covers. */
    callIds: z.array(z.string().min(1).max(64)).min(1).max(50),
    oneOff: z.boolean().default(false),
    confidence: Confidence,
    sourceRef: SourceRef,
    rationale: Rationale,
  })
  .strict();
export type AgentDecision = z.infer<typeof AgentDecision>;

/**
 * A multi-step pipeline whose calls share a workflowName + workflowRunId.
 * Batch jobs, crons and pipelines are workflows — never sessions.
 */
const WorkflowDecision = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName,
    callIds: z.array(z.string().min(1).max(64)).min(1).max(50),
    /** How to derive the per-run id that ties the steps together. */
    runIdSource: ValueSource,
    confidence: Confidence,
    sourceRef: SourceRef,
    rationale: Rationale,
  })
  .strict();
export type WorkflowDecision = z.infer<typeof WorkflowDecision>;

/**
 * A real end-user conversation thread. Only genuine back-and-forth qualifies —
 * one-off calls, background jobs, batches and pipelines must not be labelled
 * with a sessionId.
 */
const SessionDecision = z
  .object({
    id: z.string().min(1).max(64),
    /** Human label for the review UI, e.g. "Support chat". */
    label: z.string().min(1).max(48),
    callIds: z.array(z.string().min(1).max(64)).min(1).max(50),
    /** How to derive the conversation id, e.g. "the thread id on the request". */
    sessionIdSource: ValueSource,
    confidence: Confidence,
    sourceRef: SourceRef,
    rationale: Rationale,
  })
  .strict();
export type SessionDecision = z.infer<typeof SessionDecision>;

/**
 * Per-customer spend attribution. Only recommended when the app clearly serves
 * distinct end-customers or tenants; `recommended: false` is the common and
 * correct answer for a single-tenant app.
 */
const CustomerDecision = z
  .object({
    recommended: z.boolean(),
    /** How to derive customer.id. Required when recommended. */
    idSource: ValueSource.optional(),
    nameSource: ValueSource.optional(),
    imageUrlSource: ValueSource.optional(),
    confidence: Confidence,
    rationale: Rationale,
  })
  .strict()
  .refine((c) => !c.recommended || Boolean(c.idSource), {
    message: "idSource is required when customer attribution is recommended",
  });
export type CustomerDecision = z.infer<typeof CustomerDecision>;

const Decisions = z
  .object({
    agents: z.array(AgentDecision).max(40).default([]),
    workflows: z.array(WorkflowDecision).max(20).default([]),
    sessions: z.array(SessionDecision).max(20).default([]),
    customer: CustomerDecision,
  })
  .strict();
export type Decisions = z.infer<typeof Decisions>;

// ---------------------------------------------------------------------------
// DetectedPlan — what the agent uploads before touching any code
// ---------------------------------------------------------------------------

export const DetectedPlan = z
  .object({
    version: z.literal(PLAN_VERSION),
    sdk: SdkInfo,
    /** Whether the repo has a React UI — decides if the HUD is offered. */
    hasReactUi: z.boolean().default(false),
    /** The architecture map, in the public Scan contract's exact shape. */
    scan: ScanData,
    calls: z.array(CallSite).max(200).default([]),
    decisions: Decisions,
  })
  .strict()
  .superRefine((plan, ctx) => {
    const callIds = new Set(plan.calls.map((c) => c.id));
    const seen = new Set<string>();
    for (const c of plan.calls) {
      if (seen.has(c.id)) {
        ctx.addIssue({ code: "custom", path: ["calls"], message: "call ids must be unique" });
        break;
      }
      seen.add(c.id);
    }
    const groups = [
      ["agents", plan.decisions.agents],
      ["workflows", plan.decisions.workflows],
      ["sessions", plan.decisions.sessions],
    ] as const;
    for (const [key, list] of groups) {
      for (const d of list) {
        for (const id of d.callIds) {
          if (!callIds.has(id)) {
            ctx.addIssue({
              code: "custom",
              path: ["decisions", key],
              message: `unknown call id "${id}"`,
            });
          }
        }
      }
    }
  });
export type DetectedPlan = z.infer<typeof DetectedPlan>;

/**
 * What the agent receives back once the user approves. Stage 1 hands back the
 * decisions unchanged (the review UI is read-only); the shape is separate from
 * DetectedPlan so Stage 2 can return user-edited decisions without the agent
 * needing to change how it reads them.
 */
export const ApprovedPlan = z
  .object({
    version: z.literal(PLAN_VERSION),
    decisions: Decisions,
  })
  .strict();
export type ApprovedPlan = z.infer<typeof ApprovedPlan>;

// ---------------------------------------------------------------------------
// PlanEdits — what the review UI may change before approving (Stage 2)
// ---------------------------------------------------------------------------
//
// The browser never sends a whole Decisions object: it sends a small patch
// keyed by decision id, and the server applies it onto the DETECTED decisions.
// That keeps callIds, sourceRefs, rationales and confidences server-
// authoritative — an edited approval can rename things and adjust sources,
// never invent call sites or rewrite the evidence.

const AgentEdit = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName.optional(),
    oneOff: z.boolean().optional(),
  })
  .strict();

const WorkflowEdit = z
  .object({
    id: z.string().min(1).max(64),
    name: StaticName.optional(),
    runIdSource: ValueSource.optional(),
  })
  .strict();

const SessionEdit = z
  .object({
    id: z.string().min(1).max(64),
    label: z.string().min(1).max(48).optional(),
    sessionIdSource: ValueSource.optional(),
  })
  .strict();

const CustomerEdit = z
  .object({
    recommended: z.boolean().optional(),
    idSource: ValueSource.optional(),
  })
  .strict();

export const PlanEdits = z
  .object({
    agents: z.array(AgentEdit).max(40).default([]),
    workflows: z.array(WorkflowEdit).max(20).default([]),
    sessions: z.array(SessionEdit).max(20).default([]),
    customer: CustomerEdit.optional(),
  })
  .strict();
export type PlanEdits = z.infer<typeof PlanEdits>;

export type ApplyEditsResult =
  | {
      ok: true;
      decisions: Decisions;
      /** Decisions that actually changed — 0 means the edits were all no-ops. */
      editedCount: number;
    }
  | { ok: false; errors: string[] };

/** Trimmed value, or undefined when the edit is absent or trims to nothing —
 *  an all-whitespace input falls back to the detected value instead of
 *  producing an empty name. */
function cleaned(value: string | undefined): string | undefined {
  const t = value?.trim();
  return t ? t : undefined;
}

/**
 * Apply user edits onto the detected decisions, producing what the agent will
 * receive. Pure. Unknown ids are errors (the UI can only edit what was
 * detected); the merged result is re-validated through `Decisions`, so caps
 * and the customer `recommended → idSource` invariant hold no matter what the
 * browser sent.
 */
export function applyPlanEdits(
  detected: Decisions,
  edits: PlanEdits,
): ApplyEditsResult {
  const errors: string[] = [];
  let editedCount = 0;

  function mergeList<
    T extends { id: string },
    E extends { id: string },
  >(
    kind: string,
    list: T[],
    patches: E[],
    apply: (item: T, patch: E) => T,
  ): T[] {
    const byId = new Map(list.map((d) => [d.id, d] as const));
    for (const patch of patches) {
      const cur = byId.get(patch.id);
      if (!cur) {
        errors.push(`decisions.${kind}: unknown id "${patch.id}"`);
        continue;
      }
      const next = apply(cur, patch);
      if (JSON.stringify(next) !== JSON.stringify(cur)) {
        editedCount += 1;
        byId.set(patch.id, next);
      }
    }
    return list.map((d) => byId.get(d.id)!);
  }

  const agents = mergeList(
    "agents",
    detected.agents,
    edits.agents,
    (a, e) => ({
      ...a,
      name: cleaned(e.name) ?? a.name,
      oneOff: e.oneOff ?? a.oneOff,
    }),
  );
  const workflows = mergeList(
    "workflows",
    detected.workflows,
    edits.workflows,
    (w, e) => ({
      ...w,
      name: cleaned(e.name) ?? w.name,
      runIdSource: cleaned(e.runIdSource) ?? w.runIdSource,
    }),
  );
  const sessions = mergeList(
    "sessions",
    detected.sessions,
    edits.sessions,
    (s, e) => ({
      ...s,
      label: cleaned(e.label) ?? s.label,
      sessionIdSource: cleaned(e.sessionIdSource) ?? s.sessionIdSource,
    }),
  );

  let customer = detected.customer;
  if (edits.customer) {
    const next = {
      ...customer,
      recommended: edits.customer.recommended ?? customer.recommended,
      idSource: cleaned(edits.customer.idSource) ?? customer.idSource,
    };
    if (JSON.stringify(next) !== JSON.stringify(customer)) {
      editedCount += 1;
      customer = next;
    }
  }

  if (errors.length > 0) return { ok: false, errors };

  const parsed = Decisions.safeParse({ agents, workflows, sessions, customer });
  if (!parsed.success) return { ok: false, errors: flatten(parsed.error.issues) };
  return { ok: true, decisions: parsed.data, editedCount };
}

// ---------------------------------------------------------------------------
// AppliedReport — what the agent uploads after editing the repo
// ---------------------------------------------------------------------------

const AppliedCall = z
  .object({
    id: z.string().min(1).max(64),
    instrumented: z.boolean(),
    /** Why it was skipped, when it wasn't instrumented. */
    note: z.string().max(160).optional(),
  })
  .strict();

export const AppliedReport = z
  .object({
    version: z.literal(PLAN_VERSION),
    /** The map as it stands after instrumentation — powers the after-state diff. */
    scan: ScanData,
    calls: z.array(AppliedCall).max(200).default([]),
    /** Repo-relative paths only. No diffs, no contents. */
    filesChanged: z.array(z.string().min(1).max(200)).max(100).default([]),
    /** Anything the user should know, e.g. "flush() needed in the cron entry". */
    warnings: z.array(z.string().min(1).max(200)).max(20).default([]),
    hudEnabled: z.boolean().default(false),
  })
  .strict();
export type AppliedReport = z.infer<typeof AppliedReport>;

/** The stage an agent gave up at, reported on failure. */
export const FailureStage = z.enum(["detect", "apply", "verify"]);
export type FailureStage = z.infer<typeof FailureStage>;

// ---------------------------------------------------------------------------
// Validation helpers — same shape as validateScan (scan.ts)
// ---------------------------------------------------------------------------

export interface PlanValidateOk<T> {
  ok: true;
  data: T;
}
export interface PlanValidateErr {
  ok: false;
  /** Human-readable lines like `decisions.agents.0.name: too long`. */
  errors: string[];
}

function flatten(issues: z.ZodIssue[]): string[] {
  return issues.map((issue) => {
    const path = issue.path.join(".") || "(root)";
    return `${path}: ${issue.message}`;
  });
}

export function validateDetectedPlan(
  input: unknown,
): PlanValidateOk<DetectedPlan> | PlanValidateErr {
  const res = DetectedPlan.safeParse(input);
  if (res.success) return { ok: true, data: res.data };
  return { ok: false, errors: flatten(res.error.issues) };
}

export function validateAppliedReport(
  input: unknown,
): PlanValidateOk<AppliedReport> | PlanValidateErr {
  const res = AppliedReport.safeParse(input);
  if (res.success) return { ok: true, data: res.data };
  return { ok: false, errors: flatten(res.error.issues) };
}

// ---------------------------------------------------------------------------
// Graph audit — degenerate-map detection
// ---------------------------------------------------------------------------

/**
 * Structural sanity checks on the architecture map, beyond what the schema can
 * express. A graph that is just the decisions list re-drawn — all agent nodes,
 * barely any wiring, no models or stores — defeats the review page: the user
 * can't judge a plan against a picture that isn't their system. These lines
 * join the 422 `details` on upload, so the agent self-corrects and retries.
 *
 * Thresholds are deliberately loose: a tiny repo with two agents and a route
 * passes untouched. Only maps that are BOTH sizable and degenerate fail.
 */
export function auditPlanGraph(plan: DetectedPlan): string[] {
  const { nodes, edges } = plan.scan.graph;
  const errors: string[] = [];
  const ofKind = (kind: GraphNode["kind"]) =>
    nodes.filter((n) => n.kind === kind);

  if (plan.calls.length > 0 && ofKind("model").length === 0) {
    errors.push(
      "scan.graph: no model nodes — add one model node per distinct model the calls use, wired from the agents that call it",
    );
  }

  const agents = ofKind("agent");
  if (nodes.length >= 8 && agents.length / nodes.length > 0.8) {
    errors.push(
      `scan.graph: ${agents.length} of ${nodes.length} nodes are agents — this is the decisions list re-drawn, not the architecture; add the models, services, stores and third-party APIs the flows touch`,
    );
  }

  if (nodes.length >= 6 && edges.length * 2 < nodes.length) {
    errors.push(
      `scan.graph: only ${edges.length} edges for ${nodes.length} nodes — most of the map floats unconnected; wire each flow end to end, entry through model`,
    );
  }

  if (nodes.length >= 6) {
    const connected = new Set(edges.flatMap((e) => [e.from, e.to]));
    const stranded = agents.filter((n) => !connected.has(n.id));
    if (agents.length >= 3 && stranded.length * 2 > agents.length) {
      errors.push(
        `scan.graph: ${stranded.length} of ${agents.length} agent nodes have no edges at all — connect each agent FROM what triggers it and TO what it uses`,
      );
    }
    if (ofKind("entry").length === 0 && ofKind("cron").length === 0) {
      errors.push(
        "scan.graph: no entry or cron nodes — add the real routes, pages, webhooks or scheduled jobs that trigger the AI work",
      );
    }
  }

  return errors;
}

// ---------------------------------------------------------------------------
// Summary — the one-line headline on the review page
// ---------------------------------------------------------------------------

export interface PlanSummary {
  agents: number;
  workflows: number;
  sessions: number;
  calls: number;
}

/** Counts for "Foglamp found 4 agents, 2 workflows, …". */
export function summarizePlan(plan: DetectedPlan): PlanSummary {
  return {
    agents: plan.decisions.agents.length,
    workflows: plan.decisions.workflows.length,
    sessions: plan.decisions.sessions.length,
    calls: plan.calls.length,
  };
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
import { z } from "zod";

/** Max label length for graph nodes — keeps node cards a predictable width. */
export const MAX_NODE_LABEL = 28;

/**
 * The kinds of things that appear in a codebase's AI flow map. Each maps to a
 * fixed color + glyph in the renderer — the agent only tags, never styles.
 *
 *  - entry:    an entry point / trigger (route, webhook, page, command)
 *  - cron:     a scheduled / recurring job
 *  - agent:    an agent or named generateText/streamText flow
 *  - model:    an LLM (tag `domain` with the provider, e.g. "anthropic.com")
 *  - tool:     a tool/function the model can call (Exa, Firecrawl, a DB query…)
 *  - service:  an internal business-logic module/pipeline (billing, ingestion,
 *              a queue worker, a domain service) — code the project owns
 *  - store:    a datastore (Postgres, ClickHouse, Redis, a vector index…)
 *  - external: a third-party service/API the flow talks to
 */
export const NodeKind = z.enum([
  "entry",
  "cron",
  "agent",
  "model",
  "tool",
  "service",
  "store",
  "external",
]);
export type NodeKind = z.infer<typeof NodeKind>;

/**
 * Optional edge semantics — what the connection *does*. Rendered quietly:
 * revealed when the viewer traces a flow, unlike an explicit `label` which is
 * always visible.
 */
export const EdgeKind = z.enum(["calls", "reads", "writes", "triggers"]);
export type EdgeKind = z.infer<typeof EdgeKind>;

/** A logo-bearing item in the left rail (a model, tool, or integration). */
const RailItem = z.object({
  /** Stable id, lowercase-kebab (e.g. "gpt-4o", "exa"). */
  id: z.string().min(1).max(64),
  /** Human label shown on the chip (e.g. "GPT-4o", "Exa"). */
  label: z.string().min(1).max(40),
  /** Favicon domain for the logo (e.g. "openai.com"). Omit for a glyph fallback. */
  domain: z.string().min(1).max(120).optional(),
});
export type RailItem = z.infer<typeof RailItem>;

const GraphNode = z.object({
  /** Unique within the graph; referenced by edges. */
  id: z.string().min(1).max(64),
  label: z.string().min(1).max(MAX_NODE_LABEL),
  kind: NodeKind,
  /** Favicon domain for a logo on the node (mostly for model/tool/external). */
  domain: z.string().min(1).max(120).optional(),
  /** One short clarifying line (e.g. a model name under an agent). */
  sub: z.string().max(40).optional(),
  /** Longer context shown on click (e.g. file path, schedule, what it does). */
  detail: z.string().max(200).optional(),
  /** Pipeline stage this node belongs to (e.g. "Setup pipeline"). Nodes sharing
   *  a group render as one labeled vertical stack. */
  group: z.string().min(1).max(24).optional(),
  /** Where this lives in the repo (e.g. "src/agents/support.ts:42"). */
  sourceRef: z.string().min(1).max(120).optional(),
});
export type GraphNode = z.infer<typeof GraphNode>;

const GraphEdge = z.object({
  from: z.string().min(1).max(64),
  to: z.string().min(1).max(64),
  /** Optional short edge label (e.g. "on alert", "retry"). */
  label: z.string().max(24).optional(),
  /** Optional edge semantics; used as the label when `label` is omitted. */
  kind: EdgeKind.optional(),
});
export type GraphEdge = z.infer<typeof GraphEdge>;

export const ScanData = z
  .object({
    /** Schema version so the renderer can evolve without breaking old files. */
    version: z.literal(1),

    project: z.object({
      name: z.string().min(1).max(48),
      /** url-safe slug used in the footer (e.g. "foglamp"). */
      slug: z
        .string()
        .min(1)
        .max(48)
        .regex(/^[a-z0-9-]+$/, "slug must be lowercase letters, numbers, and dashes"),
      /** One-line description of the project. */
      tagline: z.string().max(80).optional(),
      /** Favicon domain for the project icon (e.g. the project's site). */
      iconDomain: z.string().max(120).optional(),
      /** ISO date (YYYY-MM-DD) the scan was generated. */
      date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "date must be YYYY-MM-DD"),
    }),

    /** Headline counts for the left-rail stat grid. */
    stats: z.object({
      agents: z.number().int().min(0).max(9999),
      models: z.number().int().min(0).max(9999),
      tools: z.number().int().min(0).max(9999),
      integrations: z.number().int().min(0).max(9999),
    }),

    /** The most-used models, ranked. Max 3 so the rail list stays tidy. */
    topModels: z.array(RailItem).max(3).default([]),
    /** The most-used tools. Max 10 — the rail scrolls. */
    topTools: z.array(RailItem).max(10).default([]),
    /** Third-party integrations. Max 10 — the rail scrolls. */
    topIntegrations: z.array(RailItem).max(10).default([]),

    /** The flow map — one big map, business logic included. Caps exist only
     *  to bound pathological payloads; big maps are welcome (the viewer pans). */
    graph: z
      .object({
        nodes: z.array(GraphNode).min(1).max(60),
        edges: z.array(GraphEdge).max(120).default([]),
      })
      .refine(
        (g) => {
          const ids = new Set(g.nodes.map((n) => n.id));
          return g.edges.every((e) => ids.has(e.from) && ids.has(e.to));
        },
        { message: "every edge must reference existing node ids" },
      )
      .refine((g) => new Set(g.nodes.map((n) => n.id)).size === g.nodes.length, {
        message: "node ids must be unique",
      }),
  })
  .strict();

export type ScanData = z.infer<typeof ScanData>;

export interface ValidateOk {
  ok: true;
  data: ScanData;
}
export interface ValidateErr {
  ok: false;
  /** Human-readable lines like `topModels: array must contain at most 3 element(s)`. */
  errors: string[];
}

/**
 * Validate an unknown value (typically `JSON.parse` of an uploaded scan)
 * against the contract. Returns either the parsed, typed data or a flat list of
 * friendly error strings.
 */
export function validateScan(input: unknown): ValidateOk | ValidateErr {
  const res = ScanData.safeParse(input);
  if (res.success) return { ok: true, data: res.data };
  const errors = res.error.issues.map((issue) => {
    const path = issue.path.join(".") || "(root)";
    return `${path}: ${issue.message}`;
  });
  return { ok: false, errors };
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
import { z } from "zod";

// ---------------------------------------------------------------------------
// Foglamp native ingest wire contract — v1.
//
// Producer: foglamp (maps the AI SDK v7 Telemetry hooks onto this).
// Consumer: apps/ingest (validates, prices, flattens to ClickHouse span rows).
// Also imported by packages/api for typed reads. This is the single source of
// truth for the wire shape — nothing here is recomputed downstream except cost
// (added at ingest) and project scoping (derived from the API key).
// ---------------------------------------------------------------------------

/**
 * Span classification. `agent` is the root span representing the whole
 * top-level `generateText`/`streamText` call (the trace); `llm` is a single
 * model step; `tool` is a tool execution. Sliced by at query time, so adding a
 * variant later is cheap.
 */
export const SPAN_TYPES = [
  "agent",
  "llm",
  "tool",
  "embedding",
  "other",
] as const;
export const spanTypeSchema = z.enum(SPAN_TYPES);
export type SpanType = z.infer<typeof spanTypeSchema>;

export const SPAN_STATUSES = ["ok", "error", "aborted"] as const;
export const spanStatusSchema = z.enum(SPAN_STATUSES);
export type SpanStatus = z.infer<typeof spanStatusSchema>;

/**
 * Token/usage counts carried on a span (primarily `llm`). Every field is
 * optional because providers vary in what they report; absence is meaningful
 * (it must not be coerced to 0, which would imply free). These map onto the
 * eight OpenRouter cost dimensions at ingest.
 */
export const usageSchema = z
  .object({
    inputTokens: z.number().int().nonnegative().optional(),
    outputTokens: z.number().int().nonnegative().optional(),
    totalTokens: z.number().int().nonnegative().optional(),
    reasoningTokens: z.number().int().nonnegative().optional(),
    cachedInputTokens: z.number().int().nonnegative().optional(),
    cacheWriteInputTokens: z.number().int().nonnegative().optional(),
    imageCount: z.number().int().nonnegative().optional(),
    webSearchCount: z.number().int().nonnegative().optional(),
    // Defaults to 1 per llm span at ingest when the model prices per-request.
    requestCount: z.number().int().nonnegative().optional(),
  })
  .strict();
export type Usage = z.infer<typeof usageSchema>;

// Free-form string→string map (mirrors ClickHouse Map(String, String)).
// Bounded so a single span can't carry an unbounded number of keys or huge
// values (wide-row amplification). Keys ≤128 chars, values ≤1024, ≤64 entries.
export const metadataSchema = z
  .record(z.string().max(128), z.string().max(1024))
  .refine((m) => Object.keys(m).length <= 64, {
    message: "metadata may have at most 64 keys",
  });
export type Metadata = z.infer<typeof metadataSchema>;

// The end-customer a trace is serving, for per-customer cost attribution. Only
// `id` is required (the stable grouping key, denormalized onto every span row);
// `name`/`imageUrl` are display-only and stored in a separate dimension table.
export const customerSchema = z
  .object({
    id: z.string().min(1).max(128),
    name: z.string().max(256).optional(),
    imageUrl: z.string().url().max(2048).optional(),
  })
  .strict();
export type Customer = z.infer<typeof customerSchema>;

const MAX_PAYLOAD_CHARS = 1_000_000; // 1MB soft cap per input/output blob.

export const spanSchema = z
  .object({
    spanId: z.string().min(1).max(128),
    parentSpanId: z.string().min(1).max(128).optional(),
    spanType: spanTypeSchema,
    name: z.string().max(512),

    // Epoch milliseconds. endTime >= startTime is enforced on the span.
    startTime: z.number().int().nonnegative(),
    endTime: z.number().int().nonnegative(),

    status: spanStatusSchema.default("ok"),
    errorMessage: z.string().max(8192).optional(),

    // Model attribution (llm spans).
    provider: z.string().max(128).optional(),
    modelId: z.string().max(256).optional(),
    usage: usageSchema.optional(),
    // Time-to-first-token, read from the AI SDK step performance object.
    ttftMs: z.number().nonnegative().optional(),

    // Deprecated: intra-stream sample arrays for the removed TPS-curve/replay
    // feature. Current SDKs no longer send them; kept optional so `.strict()`
    // doesn't reject older deployed SDKs that still do. Ignored at ingest.
    chunkOffsets: z.array(z.number().int().nonnegative()).max(200).optional(),
    chunkTokens: z.array(z.number().int().nonnegative()).max(200).optional(),
    reasoningOffsets: z
      .array(z.number().int().nonnegative())
      .max(200)
      .optional(),
    reasoningChunkTokens: z
      .array(z.number().int().nonnegative())
      .max(200)
      .optional(),
    // Total wall-clock ms spent inside reasoning blocks for this step.
    reasoningDurationMs: z.number().int().nonnegative().optional(),

    // Optional, possibly-large payloads (JSON-encoded by the SDK).
    input: z.string().max(MAX_PAYLOAD_CHARS).optional(),
    output: z.string().max(MAX_PAYLOAD_CHARS).optional(),

    // JSON catalog of tools the model was offered for this call (name →
    // {description, JSON-Schema params}). Stamped on llm + agent spans only.
    toolCatalog: z.string().max(MAX_PAYLOAD_CHARS).optional(),

    // The system prompt / agent instructions the run was started with, as
    // plain text. Stamped on the root agent span only; the SDK omits it when
    // `recordInputs` or `recordSystemPrompt` is off.
    systemPrompt: z.string().max(MAX_PAYLOAD_CHARS).optional(),

    // Pure model-call wall-clock for the step (ms): the provider invocation
    // only, excluding client-side tool execution. The llm span still covers the
    // whole step (model + tools); tool time is `durationMs - modelCallMs`.
    // v7-only (derived from the language-model-call lifecycle); absent in
    // v4-v6 wrap and in non-model spans.
    modelCallMs: z.number().int().nonnegative().optional(),

    // Official AI SDK step `performance` statistics (v7 beta/canary only; absent on
    // v4-v6 wrap, older v7, and non-model spans). `responseTimeMs` is the
    // provider response wall-clock and also feeds `modelCallMs`. The TPS fields
    // are floats (rates, not counts). `chunkJitter` is the inter-output-chunk
    // gap distribution for streaming steps with >=2 chunks; values are ms and
    // may be fractional (avg in particular), rounded to integers at ingest for
    // the UInt32 columns (avg kept as a float).
    responseTimeMs: z.number().int().nonnegative().optional(),
    effectiveOutputTps: z.number().nonnegative().optional(),
    effectiveTotalTps: z.number().nonnegative().optional(),
    outputTps: z.number().nonnegative().optional(),
    inputTps: z.number().nonnegative().optional(),
    chunkJitter: z
      .object({
        min: z.number().nonnegative(),
        p10: z.number().nonnegative(),
        median: z.number().nonnegative(),
        avg: z.number().nonnegative(),
        p90: z.number().nonnegative(),
        max: z.number().nonnegative(),
      })
      .strict()
      .optional(),

    // OpenAI-style model build fingerprint (provider metadata). Lets a drift in
    // the served model weights be detected across otherwise-identical calls.
    systemFingerprint: z.string().max(256).optional(),

    // JSON blob of provider safety ratings (Google/others), as reported. No
    // logprobs are captured. Absent when the provider reports none.
    safetyMetadata: z.string().max(16_384).optional(),

    // JSON array of RAG/grounding citations (StepResult.sources): url/document
    // references the model grounded on. Recorded only when output capture is on.
    sources: z.string().max(MAX_PAYLOAD_CHARS).optional(),

    // Rate-limit headroom, normalized cross-provider from the response headers
    // (OpenAI `x-ratelimit-*`, Anthropic `anthropic-ratelimit-*`). Only the
    // rate-limit headers are read — no other headers are stored. `*ResetMs` is
    // milliseconds until the window resets. Any subset may be present.
    rateLimit: z
      .object({
        requestsLimit: z.number().int().nonnegative().optional(),
        requestsRemaining: z.number().int().nonnegative().optional(),
        requestsResetMs: z.number().int().nonnegative().optional(),
        tokensLimit: z.number().int().nonnegative().optional(),
        tokensRemaining: z.number().int().nonnegative().optional(),
        tokensResetMs: z.number().int().nonnegative().optional(),
      })
      .strict()
      .optional(),

    // Span-level metadata, merged over the trace-level map (span wins).
    metadata: metadataSchema.optional(),
  })
  .strict()
  .refine((s) => s.endTime >= s.startTime, {
    message: "endTime must be >= startTime",
    path: ["endTime"],
  });
export type Span = z.infer<typeof spanSchema>;

/**
 * A trace is one top-level call plus its spans. The first-class ids and
 * trace-level metadata are denormalized onto every span row at ingest (the
 * span store indexes them per-row), so they live once here on the wire.
 */
export const traceSchema = z
  .object({
    traceId: z.string().min(1).max(128),

    traceName: z.string().max(256).optional(),
    agentName: z.string().max(256).optional(),
    workflowName: z.string().max(256).optional(),
    workflowRunId: z.string().max(128).optional(),
    sessionId: z.string().max(128).optional(),
    customer: customerSchema.optional(),

    metadata: metadataSchema.optional(),

    spans: z.array(spanSchema).min(1).max(2000),
  })
  .strict()
  .superRefine((t, ctx) => {
    // Every trace must be identifiable: a plain named trace (traceName) or a
    // trace classified under an agent (agentName). The effective display label
    // downstream is `traceName ?? agentName`.
    if (!t.traceName && !t.agentName) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Either traceName or agentName must be provided",
        path: ["traceName"],
      });
    }
    // Workflow grouping is all-or-nothing: a run id without a name (or vice
    // versa) can't be attributed to a workflow.
    if (Boolean(t.workflowName) !== Boolean(t.workflowRunId)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "workflowName and workflowRunId must be provided together",
        path: ["workflowRunId"],
      });
    }
  });
export type Trace = z.infer<typeof traceSchema>;

export const INGEST_VERSION = "v1" as const;

export const ingestPayloadSchema = z
  .object({
    version: z.literal(INGEST_VERSION),
    traces: z.array(traceSchema).min(1).max(1000),
  })
  .strict();
export type IngestPayload = z.infer<typeof ingestPayloadSchema>;

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/trace-timeline.ts; derived here under Apache-2.0.
 */
import type { TraceSpan } from "./types";

/** ClickHouse datetime string ('YYYY-MM-DD HH:MM:SS', UTC) → epoch ms. */
export function toMs(value: string): number {
	return new Date(`${value.replace(" ", "T")}Z`).getTime();
}

/** Order spans depth-first by parent so the waterfall reads top-to-bottom. */
export function orderSpans(
	spans: TraceSpan[],
): { span: TraceSpan; depth: number }[] {
	const children = new Map<string, TraceSpan[]>();
	const roots: TraceSpan[] = [];
	for (const s of spans) {
		if (s.parentSpanId && spans.some((p) => p.spanId === s.parentSpanId)) {
			const list = children.get(s.parentSpanId) ?? [];
			list.push(s);
			children.set(s.parentSpanId, list);
		} else {
			roots.push(s);
		}
	}
	const byStart = (a: TraceSpan, b: TraceSpan) =>
		toMs(a.startTime) - toMs(b.startTime);
	const out: { span: TraceSpan; depth: number }[] = [];
	const walk = (s: TraceSpan, depth: number) => {
		out.push({ span: s, depth });
		(children.get(s.spanId) ?? [])
			.sort(byStart)
			.forEach((c) => walk(c, depth + 1));
	};
	roots.sort(byStart).forEach((r) => walk(r, 0));
	return out;
}

/** Trace-relative window: absolute start (ms) and total span (ms, min 1). */
export function computeWindow(spans: TraceSpan[]): {
	start: number;
	span: number;
} {
	if (spans.length === 0) return { start: 0, span: 1 };
	const start = Math.min(...spans.map((s) => toMs(s.startTime)));
	const end = Math.max(...spans.map((s) => toMs(s.endTime)));
	return { start, span: Math.max(end - start, 1) };
}

