			<table className="w-full border-collapse text-xs tabular-nums">
				{children}
			</table>
		</div>
	),
	thead: ({ children }: ComponentProps<"thead">) => (
		<thead className="bg-muted/40 text-muted-foreground">{children}</thead>
	),
	tr: ({ children }: ComponentProps<"tr">) => (
		<tr className="border-b border-border/40 last:border-0">{children}</tr>
	),
	th: ({ children }: ComponentProps<"th">) => (
		<th className="px-3 py-2 text-left font-medium whitespace-nowrap">
			{children}
		</th>
	),
	td: ({ children }: ComponentProps<"td">) => (
		<td className="px-3 py-1.5 align-top">{children}</td>
	),
	// Streamdown wraps images in a <div> for its hover controls, but markdown puts
	// images inside paragraphs — a <div> inside a <p> is invalid HTML, and React
	// throws a hydration error on it. A bare <img> is valid wherever an image can
	// legally appear, so it renders the same in every context.
	img: ({ src, alt, ...rest }: ComponentProps<"img">) => (
		// Deliberately not an image optimizer: these are arbitrary remote URLs from model
		// output, not assets the optimizer can be pointed at.
		<img
			{...rest}
			src={typeof src === "string" ? src : undefined}
			alt={alt ?? ""}
			className="my-1.5 inline-block max-h-64 max-w-full rounded-md"
		/>
	),
	hr: () => <hr className="my-3 border-border/60" />,
};

/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted AS-IS from .reference/foglamp/apps/web/src/components/app/model-chip.tsx; derived under Apache-2.0.
 */
import { IconCpu } from "@tabler/icons-react";

import { ContextChip } from "./context-chip";
import { ModelLogo, formatModelName } from "../icons/model-logo";
import { cn } from "../lib/utils";

export type ChipModel = { modelId: string; provider: string | null };

/**
 * Static context chip for the model(s) a session or trace ran on. One model
 * shows its logo and display name; several overlap their logos (first-use
 * order, capped at three) and read "n models" with the full list in the title.
 */
export function ModelChip({ models }: { models: ChipModel[] }) {
	if (models.length === 0) return null;
	const only = models[0];
	if (models.length === 1 && only) {
		return (
			<ContextChip
				icon={(p) => (
					<ModelLogo
						provider={only.provider}
						modelId={only.modelId}
						className={p.className}
					/>
				)}
				iconClassName=""
				label={formatModelName(only.modelId)}
			/>
		);
	}
	const shown = models.slice(0, 3);
	return (
		<span title={models.map((m) => formatModelName(m.modelId)).join(", ")}>
			<ContextChip
				icon={(p) => (
					<span className={cn("flex items-center -space-x-1.5", p.className)}>
						{shown.map((m) => (
							<span
								key={m.modelId}
								className="flex size-4 items-center justify-center rounded-full bg-card ring-1 ring-card"
							>
								<ModelLogo
									provider={m.provider}
									modelId={m.modelId}
									className="size-3"
								/>
							</span>
						))}
						{models.length > shown.length && (
							<IconCpu className="size-3 text-muted-foreground" />
						)}
					</span>
				)}
				iconClassName="w-auto"
				label={`${models.length} models`}
			/>
		</span>
	);
}

