/** One column of a `TableRowsSkeleton` row. Omit `w` for an empty cell (e.g.
 * an actions column). `icon` adds a small square blob before the text blob. */
export type SkeletonCol = {
  w?: string;
  align?: "left" | "right";
  icon?: boolean;
  /** Width class for a second, smaller meta line under the main blob —
   * for two-line details cells (traces/sessions). The two lines reproduce
   * the real cell's line boxes (h-5 name + gap-1 + mt-0.5 + h-4 meta), so
   * the skeleton row height matches the data rows without hardcoding it. */
  sub?: string;
};

/**
 * Placeholder body rows for a list table while its query is in flight. The
 * page's chrome (toolbar, column headers) renders immediately; only these
 * rows shimmer, one blob per column, mirroring the real cells' alignment.
 * Pair with a `table-fixed` Table so the skeleton→data swap can't shift
 * column widths.
 */
export function TableRowsSkeleton({
  rows = 3,
  cols,
  rowHeight = "h-12",
}: {
  rows?: number;
  cols: readonly SkeletonCol[];
  /** Height class matching the real rows, when they're taller than the
   * standard h-12 (e.g. two-line cells). */
  rowHeight?: string;
}) {
  return (
    <>
      {Array.from({ length: rows }).map((_, i) => (
        <TableRow key={i}>
          {cols.map((c, j) => (
            <TableCell key={j} align={c.align} className={rowHeight}>
              {c.sub ? (
                <div className="flex flex-col gap-1">
                  <div className="flex h-5 items-center gap-2">
                    {c.icon && (
                      <Skeleton className="size-4 shrink-0 rounded-md" />
                    )}
                    <Skeleton className={cn("h-4", c.w)} />
                  </div>
                  <div className="mt-0.5 flex h-4 items-center">
                    <Skeleton className={cn("h-3", c.sub)} />
                  </div>
                </div>
              ) : (
                c.w && (
                  <div
                    className={cn(
                      "flex items-center gap-2",
                      c.align === "right" && "justify-end"
                    )}
                  >
                    {c.icon && (
                      <Skeleton className="size-4 shrink-0 rounded-md" />
                    )}
                    <Skeleton className={cn("h-4", c.w)} />
                  </div>
                )
              )}
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

export function TableSkeleton({ rows = 5 }: { rows?: number }) {
  return (
    <div className="flex flex-col gap-3">
      <Skeleton className="h-8 w-1/3" />
      <Skeleton className="h-12 w-full" />
      {Array.from({ length: rows }).map((_, i) => (
        <Skeleton key={i} className="h-7 w-full" />
      ))}
    </div>
  );
}

export function CardsSkeleton({ count = 4 }: { count?: number }) {
  return (
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-5">
      {Array.from({ length: count }).map((_, i) => (
        <Skeleton key={i} className="h-24 w-full" />
      ))}
    </div>
  );
}

/** Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted AS-IS from .reference/foglamp/apps/web/src/components/app/project-context.tsx; derived under Apache-2.0.
 */
"use client";

import { createContext, use, useCallback, useMemo, useState } from "react";

export type Project = {
  id: string;
  name: string;
  slug: string;
  url: string | null;
  orgId: string;
  orgName: string;
  orgSlug: string;
};

type ProjectContextValue = {
  projects: Project[];
  project: Project | null;
  projectId: string | null;
  setProjectId: (id: string) => void;
  isLoading: boolean;
};

const MOCK_PROJECTS: Project[] = [
  {
    id: "project_demo",
    name: "Acme Production",
    slug: "acme-production",
    url: null,
    orgId: "org_demo",
    orgName: "Acme",
    orgSlug: "acme",
  },
];

const ProjectContext = createContext<ProjectContextValue | null>(null);

/**
 * Project selection state with injectable data and a small mock default. The
 * host application owns persistence and route changes through onProjectChange.
 */
export function ProjectProvider({
  children,
  projects = MOCK_PROJECTS,
  initialProjectId,
  isLoading = false,
  onProjectChange,
}: {
  children: React.ReactNode;
  projects?: Project[];
  initialProjectId?: string | null;
  isLoading?: boolean;
  onProjectChange?: (id: string) => void;
}) {
  const [selected, setSelected] = useState<string | null>(
    initialProjectId ?? projects[0]?.id ?? null,
  );
  const setProjectId = useCallback(
    (id: string) => {
      setSelected(id);
      onProjectChange?.(id);
    },
    [onProjectChange],
  );
  const value = useMemo<ProjectContextValue>(() => {
    const project = projects.find((item) => item.id === selected) ?? null;
    return {
      projects,
      project,
      projectId: project?.id ?? null,
      setProjectId,
      isLoading,
    };
  }, [projects, selected, isLoading, setProjectId]);

  return <ProjectContext value={value}>{children}</ProjectContext>;
}

export function useProject(): ProjectContextValue {
  const ctx = use(ProjectContext);
  if (!ctx) throw new Error("useProject must be used within ProjectProvider");
  return ctx;
}
